-- FEC money for the 13 PACs whose donor lists overlap the 19 by 15%+ (plus the name/treasurer look-alikes): raised, spent, sent to candidates/committees, independent expenditures
SELECT CMTE_ID, MAX(COMMITTEE_NAME) nm, MIN(YEAR(COVERAGE_END_DATE)) y0, MAX(YEAR(COVERAGE_END_DATE)) y1, ROUND(SUM(TOTAL_RECEIPTS)/1e6,3) rec_m, ROUND(SUM(TOTAL_DISBURSEMENTS)/1e6,3) dis_m,
  ROUND(SUM(CONTRIBUTIONS_TO_OTHER_COMMITTEES)/1e6,3) to_cmtes_m, ROUND(SUM(INDEPENDENT_EXPENDITURES)/1e6,3) ie_m,
  ROUND(100*(SUM(CONTRIBUTIONS_TO_OTHER_COMMITTEES)+SUM(INDEPENDENT_EXPENDITURES))/NULLIF(SUM(TOTAL_DISBURSEMENTS),0),1) pct_to_politics, COUNT(*) cycles_rows
FROM LIBRARY_MARTS.POLITICS.POLITICS__FED_FEC_PAC_SUMMARY
WHERE CMTE_ID IN ('C00570093','C00715433','C00709113','C00710160','C00650168','C00784496','C00755694','C00681825','C00570416','C00758938','C00712885','C00710178','C00699801',
  'C00822106','C00667865','C00691329','C00691949','C00674267','C00715573')
GROUP BY CMTE_ID ORDER BY rec_m DESC
